begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,ml_private,ml_public;
select plan(13);
select ok(not has_function_privilege('anon','ml_private.complete_studio_setup(text,text,ml_private.measurement_unit,ml_private.iso_currency,text)','execute'),'anonymous setup is denied');
select ok(not has_function_privilege('anon','ml_private.delete_studio_item(uuid,text,uuid,bigint,uuid)','execute'),'anonymous cleanup is denied');
insert into auth.users(id,email) values('fa110000-0000-4000-8000-000000000001','practical-use-owner@example.test');
select set_config('request.jwt.claims','{"sub":"fa110000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
create temporary table qa_studio(id uuid);
insert into qa_studio select ml_private.complete_studio_setup('Cleanup QA','America/Los_Angeles','cm','USD','en-US');
select is(ml_private.complete_studio_setup('Cleanup QA','America/Los_Angeles','cm','USD','en-US'),(select id from qa_studio),'setup retries reuse the same studio');
select is((select count(*) from ml_private.studios where owner_user_id=auth.uid()),1::bigint,'setup creates one studio');
select is((select count(*) from ml_private.garments where studio_id=(select id from qa_studio)),0::bigint,'new studio is intentionally empty');
select set_config('ml.canonical_operation_context','on',true);
insert into ml_private.tasks(id,studio_id,title) select 'fa120000-0000-4000-8000-000000000001',id,'Cleanup task' from qa_studio;
select throws_ok($q$select ml_private.delete_studio_item((select id from qa_studio),'task','fa120000-0000-4000-8000-000000000001',9,'fa130000-0000-4000-8000-000000000001')$q$,'40001','This item changed on another device. Refresh and review the removal again.','stale confirmation does not delete');
select is(ml_private.delete_studio_item((select id from qa_studio),'task','fa120000-0000-4000-8000-000000000001',1,'fa130000-0000-4000-8000-000000000002')->>'status','applied','server acknowledges task deletion');
select is(ml_private.delete_studio_item((select id from qa_studio),'task','fa120000-0000-4000-8000-000000000001',1,'fa130000-0000-4000-8000-000000000002')->>'status','duplicate','delete retries are idempotent');
select is((select count(*) from ml_private.sync_tombstones where studio_id=(select id from qa_studio) and client_id='fa120000-0000-4000-8000-000000000001'),1::bigint,'deletion records a tombstone');
select is(ml_private.commit_canonical_operation('fa130000-0000-4000-8000-000000000003',(select id from qa_studio),null,'sync','[{"entityType":"tasks","entityId":"fa120000-0000-4000-8000-000000000001","action":"insert","baseRevision":null,"row":{"title":"Stale task"}}]')#>>'{conflicts,0,reason}','deleted','stale-device insert cannot resurrect deleted content');
insert into ml_private.garments(id,studio_id,title,garment_code) select 'fa140000-0000-4000-8000-000000000001',id,'Protected garment','QA-PROTECTED' from qa_studio;
insert into ml_private.technical_specs(id,studio_id,garment_id,base_size,unit,status) select 'fa150000-0000-4000-8000-000000000001',id,'fa140000-0000-4000-8000-000000000001','M','cm','approved' from qa_studio;
select throws_ok($q$select ml_private.delete_studio_item((select id from qa_studio),'garment','fa140000-0000-4000-8000-000000000001',1,'fa130000-0000-4000-8000-000000000004')$q$,'23514','This garment has retained evidence or stories. Archive it instead.','approved garment evidence blocks deletion');
select throws_ok($q$select ml_private.delete_studio_item('fa160000-0000-4000-8000-000000000001','task','fa120000-0000-4000-8000-000000000001',1,'fa130000-0000-4000-8000-000000000005')$q$,'42501','An active Studio owner must confirm this removal.','cross-tenant cleanup is denied');
select is((select count(*) from ml_private.garments where studio_id=(select id from qa_studio)),1::bigint,'blocked deletion retains garment');
select * from finish();
rollback;
